-- Seeded from products.ts. GENERATED — regenerate if that data changes.
-- Product and variant ids are the ones already in the code, so slugs and the
-- aw-<slug> artwork keys that /art depends on stay exactly as they are.

insert into public.products
  (id, sku, slug, type, line, title_en, title_ar, flavor_id, cocoa_pct,
   ingredients_en, ingredients_ar, story_en, story_ar, allergens, badges, art_card,
   rating, review_count, pairs_with, occasions, sort_order)
values
  ('p-milk','JAZ-BAR-MILK-90','signature-milk','bar','signature','Signature Milk','الحليب التوقيعية','milk',38,'Cocoa butter, whole milk powder, cane sugar, cocoa mass, soya lecithin, natural vanilla.','زبدة كاكاو، حليب كامل الدسم مجفف، سكر قصب، كتلة كاكاو، ليسيثين الصويا، فانيليا طبيعية.','Our north star. A gently caramelised milk chocolate, conched slow until it turns to silk — the bar every other flavor is measured against.','نجمنا القطبي. شوكولاتة بالحليب بكراميل خفيف، تُملّس ببطءٍ حتى تصير حريرًا — اللوح الذي تُقاس عليه كل النكهات.','[{"en":"Milk","ar":"حليب"},{"en":"Soya","ar":"صويا"},{"en":"May contain nuts","ar":"قد يحتوي على مكسرات"}]'::jsonb,'{bestseller}','{"artworkTitle":{"en":"Shepherds'' Memories","ar":"ذاكرة الرعاة"},"artistName":{"en":"Afnan Ali","ar":"أفنان علي"},"description":{"en":"Inspired by the lives of shepherds across Jazan''s mountains and valleys, the artwork portrays the simplicity of rural life and the harmony between people and nature. It celebrates authenticity, patience, and the enduring connection to the land.","ar":"استُلهم هذا العمل من حياة الرعاة في جبال وسهول جازان، ويجسد بساطة الحياة وانسجام الإنسان مع الطبيعة. وتحتفي اللوحة بقيم الأصالة والصبر والارتباط العميق بالأرض."}}'::jsonb,4.9,218,'{"p-coffee","p-dark"}','{"everyday","gifting"}',0),
  ('p-lavender','JAZ-BAR-LAV-90','lavender-milk','bar','signature','Lavender Milk','الخزامى بالحليب','lavender',38,'Cocoa butter, whole milk powder, cane sugar, cocoa mass, culinary lavender, soya lecithin.','زبدة كاكاو، حليب كامل الدسم مجفف، سكر قصب، كتلة كاكاو، خزامى للطهي، ليسيثين الصويا.','A single breath of culinary lavender folded into milk chocolate — floral, never soapy. Restraint is the whole trick.','نفَسٌ واحد من خزامى الطهي يُطوى في شوكولاتة الحليب — عطريّ دون أن يكون صابونيًا. الاتزان هو السرّ كله.','[{"en":"Milk","ar":"حليب"},{"en":"Soya","ar":"صويا"}]'::jsonb,'{bestseller}','{"artworkTitle":{"en":"When the Fields Bloom","ar":"حين تزهر الحقول"},"artistName":{"en":"Afnan Ali","ar":"أفنان علي"},"description":{"en":"Inspired by Jazan''s aromatic plants, the artwork portrays a woman carrying a basket filled with lavender and local herbs. It celebrates the harmony between people and nature and the region''s rich botanical heritage.","ar":"استُلهم هذا العمل من النباتات العطرية التي تزخر بها جازان، ويجسد امرأة تحمل سلة مليئة بالخزامى والنباتات المحلية. وتعكس اللوحة انسجام الإنسان مع الطبيعة وثراء الإرث العطري للمنطقة."}}'::jsonb,4.7,96,'{"p-rose","p-jasmine"}','{"gifting","ramadan"}',1),
  ('p-rose','JAZ-BAR-ROSE-90','damascena-rose','bar','limited','Damascena Rose','الورد الدمشقي','rose',38,'Cocoa butter, whole milk powder, cane sugar, cocoa mass, Taif rose petals, soya lecithin.','زبدة كاكاو، حليب كامل الدسم مجفف، سكر قصب، كتلة كاكاو، بتلات ورد طائفي، ليسيثين الصويا.','Taif rose petals, hand-folded at the last moment so the perfume survives. A limited bar that smells like a courtyard at dusk.','بتلات ورد طائفي تُطوى يدويًا في اللحظة الأخيرة كي يبقى العبير. لوحٌ محدود برائحة فناءٍ عند الغروب.','[{"en":"Milk","ar":"حليب"},{"en":"Soya","ar":"صويا"}]'::jsonb,'{limited,new}','{"artworkTitle":{"en":"When the Fields Bloom","ar":"حين تزهر الحقول"},"artistName":{"en":"Afnan Ali","ar":"أفنان علي"},"description":{"en":"Inspired by the fragrance of Jazan''s roses and aromatic plants, the artwork reflects the beauty of nature and the enduring bond between people and their environment. It celebrates one of the region''s most elegant cultural treasures.","ar":"استُلهم هذا العمل من عبير الورود والنباتات العطرية في جازان، ويجسد جمال الطبيعة وارتباط الإنسان ببيئته. وتحتفي اللوحة بأحد أرقى ملامح الهوية العطرية للمنطقة."}}'::jsonb,4.8,64,'{"p-lavender","p-jasmine"}','{"gifting","wedding"}',2),
  ('p-jasmine','JAZ-BAR-JAS-90','jazan-jasmine','bar','signature','Jazan Jasmine','فُل جازان','jasmine',38,'Cocoa butter, whole milk powder, cane sugar, cocoa mass, jasmine (الفُل) infusion, soya lecithin.','زبدة كاكاو، حليب كامل الدسم مجفف، سكر قصب، كتلة كاكاو، نقيع الفُل، ليسيثين الصويا.','The الفُل that scents Jazan evenings, infused into white-edged milk chocolate. The most local bar we make.','الفُل الذي يعطّر أمسيات جازان، منقوعٌ في شوكولاتة حليب بأطرافٍ بيضاء. أكثر ألواحنا محليّة.','[{"en":"Milk","ar":"حليب"},{"en":"Soya","ar":"صويا"}]'::jsonb,'{seasonal}','{"artworkTitle":{"en":"When the Fields Bloom","ar":"حين تزهر الحقول"},"artistName":{"en":"Afnan Ali","ar":"أفنان علي"},"description":{"en":"Inspired by the Arabian jasmine of Jazan, a timeless symbol of fragrance and beauty, the artwork portrays a woman carrying a basket of blossoms. It expresses the authenticity, generosity, and warmth that define the spirit of Jazan.","ar":"استُلهم هذا العمل من الفُل الجازاني، رمز العطر والجمال في المنطقة، ويجسد امرأة تحمل سلة من الزهور. وتعبر اللوحة عن الأصالة والكرم ودفء المجتمع الجازاني."}}'::jsonb,4.6,73,'{"p-rose","p-papaya"}','{"gifting","eid"}',3),
  ('p-papaya','JAZ-BAR-PAP-90','sun-papaya','bar','seasonal','Sun Papaya','الببايا الشمسية','papaya',38,'Cocoa butter, whole milk powder, cane sugar, cocoa mass, sun-dried Jazani papaya, soya lecithin.','زبدة كاكاو، حليب كامل الدسم مجفف، سكر قصب، كتلة كاكاو، ببايا جيزانية مجففة بالشمس، ليسيثين الصويا.','Jazani papaya, sun-dried to a chew and scattered through milk chocolate. A tropical bar with a southern accent.','ببايا جيزانية تُجفَّف بالشمس حتى تصبح مطّاطة، ثم تُنثر في شوكولاتة الحليب. لوحٌ استوائي بلكنةٍ جنوبية.','[{"en":"Milk","ar":"حليب"},{"en":"Soya","ar":"صويا"},{"en":"May contain nuts","ar":"قد يحتوي على مكسرات"}]'::jsonb,'{seasonal}','{"artworkTitle":{"en":"Papaya Harvest","ar":"حصاد البابايا"},"artistName":{"en":"Rehab Zakri","ar":"رحاب زكري"},"description":{"en":"Inspired by Jazan''s flourishing papaya orchards, the artwork captures the harvest of one of the region''s most celebrated tropical fruits. Its vibrant colors reflect the richness and abundance of Jazan''s landscape.","ar":"استُلهم هذا العمل من مزارع البابايا التي تزين جازان، ويجسد لحظة حصاد إحدى أشهر الفواكه الاستوائية في المنطقة. وتعكس ألوانه حيوية الطبيعة ووفرة الخير التي تميز جازان."}}'::jsonb,4.5,41,'{"p-mango","p-milk"}','{"everyday"}',4),
  ('p-mango','JAZ-BAR-MAN-90','jazani-mango','bar','seasonal','Jazani Mango','المانجو الجيزاني','mango',38,'Cocoa butter, whole milk powder, cane sugar, cocoa mass, Jazani mango, soya lecithin.','زبدة كاكاو، حليب كامل الدسم مجفف، سكر قصب، كتلة كاكاو، مانجو جيزاني، ليسيثين الصويا.','The pride of the Jazan orchards in a bar — bright mango against warm milk chocolate. Made only in season.','فخر بساتين جازان في لوح — مانجو ساطع أمام شوكولاتة حليب دافئة. يُصنع في موسمه فقط.','[{"en":"Milk","ar":"حليب"},{"en":"Soya","ar":"صويا"}]'::jsonb,'{seasonal,new}','{"artworkTitle":{"en":"Waves of Mango","ar":"موج المانجو"},"artistName":{"en":"Rehab Zakri","ar":"رحاب زكري"},"description":{"en":"Inspired by the meeting of Jazan''s coastline and its mango orchards, the artwork blends the blue sea with lush greenery. It celebrates the mango as one of Jazan''s most iconic agricultural treasures.","ar":"استُلهم هذا العمل من التقاء بحر جازان ببساتين المانجو، حيث تمتزج زرقة البحر بخضرة الطبيعة في مشهد يعكس جمال المنطقة. وتجسد اللوحة المانجو كأحد أبرز رموز جازان الزراعية."}}'::jsonb,4.8,52,'{"p-papaya","p-coffee"}','{"everyday","gifting"}',5),
  ('p-coffee','JAZ-BAR-COF-90','khawlani-coffee','bar','signature','Khawlani Coffee','البن الخولاني','coffee',62,'Cocoa mass, cane sugar, cocoa butter, Khawlani coffee, milk powder, soya lecithin.','كتلة كاكاو، سكر قصب، زبدة كاكاو، بن خولاني، حليب مجفف، ليسيثين الصويا.','Khawlani coffee — grown in the Jazan highlands for six centuries — ground into a darker bar. Heritage, twice over.','البن الخولاني — الذي يُزرع في مرتفعات جازان منذ ستة قرون — مطحونٌ في لوحٍ أدكن. إرثٌ مرتين.','[{"en":"Milk","ar":"حليب"},{"en":"Soya","ar":"صويا"}]'::jsonb,'{bestseller}','{"artworkTitle":{"en":"The First Harvest","ar":"الحصاد الأول"},"artistName":{"en":"Afnan Ali","ar":"أفنان علي"},"description":{"en":"Inspired by the coffee farms of Jazan, the artwork portrays a young boy carrying freshly harvested coffee cherries, marking the beginning of a tradition passed down through generations. It honors Jazan''s renowned coffee heritage.","ar":"استُلهم هذا العمل من مزارع البن الجازاني، ويجسد طفلًا يحمل سلة البن في بداية رحلة الحصاد المتوارثة عبر الأجيال. وتعكس اللوحة ارتباط الإنسان بأرضه واعتزازه بإرثه الزراعي."}}'::jsonb,4.9,134,'{"p-dark","p-milk"}','{"everyday","gifting"}',6),
  ('p-dark','JAZ-BAR-DARK-90','single-origin-dark','bar','signature','Single-Origin Dark 72%','الداكنة ٧٢٪','dark',72,'Cocoa mass, cane sugar, cocoa butter, soya lecithin.','كتلة كاكاو، سكر قصب، زبدة كاكاو، ليسيثين الصويا.','A clean, single-origin 72% for purists — bitter-bright, with a long, dry finish. Dairy-free.','داكنة نقية ٧٢٪ من منشأ واحد للمتذوّقين — مرّةٌ مشرقة بنهايةٍ طويلة جافة. خالية من الألبان.','[{"en":"Soya","ar":"صويا"},{"en":"May contain nuts","ar":"قد يحتوي على مكسرات"}]'::jsonb,'{}','{"artworkTitle":{"en":"What Remains of Us","ar":"ما يبقى منا"},"artistName":{"en":"Afnan Ali","ar":"أفنان علي"},"description":{"en":"Inspired by the timeless values that endure across generations, the artwork reflects the profound bond between people, their land, and their cultural identity. It reminds us that what truly remains is the legacy we preserve and pass on.","ar":"استُلهم هذا العمل من القيم الراسخة التي تبقى رغم تعاقب الزمن، ويجسد العلاقة العميقة بين الإنسان وأرضه وهويته. ويؤكد أن ما يبقى حقًا هو الإرث الذي نحفظه ونتناقله عبر الأجيال."}}'::jsonb,4.7,88,'{"p-coffee","p-milk"}','{"everyday"}',7),
  ('p-dark60','JAZ-BAR-DARK60-90','dark-60','bar','signature','Dark 60%','الداكنة ٦٠٪','dark60',60,'Cocoa mass, cane sugar, cocoa butter, soya lecithin.','كتلة كاكاو، سكر قصب، زبدة كاكاو، ليسيثين الصويا.','A gentler way into dark — 60% cacao, rounder and less austere than our 72%. All cocoa warmth, no bitterness to brace for.','مدخلٌ أنعم إلى الداكنة — ٦٠٪ كاكاو، أكثر استدارةً وأقل حِدّةً من ٧٢٪. دفءُ كاكاو دون مرارةٍ تتحسّب لها.','[{"en":"Soya","ar":"صويا"},{"en":"May contain nuts","ar":"قد يحتوي على مكسرات"}]'::jsonb,'{}','{"artworkTitle":{"en":"The Jazan Head Ornament","ar":"الميل الجازاني"},"artistName":{"en":"Wajd Jandali","ar":"وجد جندلي"},"description":{"en":"Inspired by the elegance of the Jazan woman and her traditional attire, the artwork highlights the iconic Meel head ornament. It celebrates a cultural heritage that continues to thrive through everyday life.","ar":"استُلهم هذا العمل من جمال المرأة الجازانية وأصالة زيّها التقليدي، ويبرز «الميل» بوصفه أحد رموز الهوية الاجتماعية. وتحتفي اللوحة بتراثٍ ما زال حاضرًا في تفاصيل الحياة اليومية."}}'::jsonb,4.6,57,'{"p-dark","p-coffee"}','{"everyday"}',8),
  ('p-seasalt','JAZ-BAR-SALT-90','sea-salt-dark','bar','signature','Sea Salt Dark','الداكنة بملح البحر','seasalt',62,'Cocoa mass, cane sugar, cocoa butter, Red Sea salt flakes, soya lecithin.','كتلة كاكاو، سكر قصب، زبدة كاكاو، رقائق ملح البحر الأحمر، ليسيثين الصويا.','Flakes of Red Sea salt scattered across dark chocolate — every bite swings between sweet and saline. A coastline in a bar.','رقائق من ملح البحر الأحمر تتناثر على شوكولاتة داكنة — كل قضمة تتأرجح بين الحلاوة والملوحة. ساحلٌ في لوح.','[{"en":"Soya","ar":"صويا"},{"en":"May contain nuts","ar":"قد يحتوي على مكسرات"}]'::jsonb,'{new}','{"artworkTitle":{"en":"White Tide","ar":"أبيض المدّ"},"artistName":{"en":"Afnan Ali","ar":"أفنان علي"},"description":{"en":"Inspired by Jazan''s historic salt fields, the artwork portrays a salt worker whose dedication reflects generations of perseverance. It celebrates the timeless relationship between the people and the sea.","ar":"استُلهم هذا العمل من ملاحات جازان التاريخية، ويجسد عامل الملح ورحلة الكفاح والصبر في جمع أحد أقدم كنوز البحر. وتحتفي اللوحة بعلاقة الإنسان بالبحر وإرثه العريق."}}'::jsonb,4.8,46,'{"p-dark","p-coffee"}','{"everyday","gifting"}',9),
  ('p-chili','JAZ-BAR-CHILI-90','chili-dark','bar','signature','Chili Dark','الداكنة بالفلفل الحار','chili',65,'Cocoa mass, cane sugar, cocoa butter, ground chili, soya lecithin.','كتلة كاكاو، سكر قصب، زبدة كاكاو، فلفل حار مطحون، ليسيثين الصويا.','Dark chocolate with a slow chili warmth that arrives only after the sweetness — a gentle heat that lingers, never a burn.','شوكولاتة داكنة بحرارة فلفلٍ هادئة لا تصل إلا بعد الحلاوة — دفءٌ لطيف يبقى، دون أن يلسع.','[{"en":"Soya","ar":"صويا"},{"en":"May contain nuts","ar":"قد يحتوي على مكسرات"}]'::jsonb,'{}','{"artworkTitle":{"en":"The Millstone","ar":"المطحنة"},"artistName":{"en":"Wajd Jandali","ar":"وجد جندلي"},"description":{"en":"Inspired by everyday life in Jazan, the artwork portrays a woman grinding chili peppers with a traditional stone mill. It honors the role of women in preserving culinary traditions across generations.","ar":"استُلهم هذا العمل من تفاصيل الحياة اليومية في جازان، ويجسد امرأة تطحن الفلفل بالطاحونة الحجرية التقليدية. وتعكس اللوحة دور المرأة في حفظ الموروث الغذائي ونقل النكهات الأصيلة."}}'::jsonb,4.5,33,'{"p-dark","p-coffee"}','{"everyday"}',10),
  ('p-banana','JAZ-BAR-BAN-90','banana-dark','bar','seasonal','Banana Dark','الداكنة بالموز','banana',55,'Cocoa mass, cane sugar, cocoa butter, sun-dried banana, soya lecithin.','كتلة كاكاو، سكر قصب، زبدة كاكاو، موز مجفف بالشمس، ليسيثين الصويا.','Sun-dried banana folded into dark chocolate — mellow, jammy sweetness leaning against a firm cocoa backbone.','موزٌ مجفف بالشمس يُطوى في شوكولاتة داكنة — حلاوةٌ ناضجة هادئة تتّكئ على عمود كاكاو راسخ.','[{"en":"Soya","ar":"صويا"},{"en":"May contain nuts","ar":"قد يحتوي على مكسرات"}]'::jsonb,'{seasonal}','{"artworkTitle":{"en":"Among the Banana Clusters","ar":"بين عناقيد الموز"},"artistName":{"en":"Rehab Zakri","ar":"رحاب زكري"},"description":{"en":"Inspired by Jazan''s abundant banana plantations, the artwork portrays lush banana clusters that blend with the land and its people. It celebrates fertility, generosity, and the tropical spirit of Jazan.","ar":"استُلهم هذا العمل من وفرة مزارع الموز في جازان، حيث تتناغم عناقيد الموز مع الأرض والإنسان في مشهد يجسد الخصوبة والعطاء. وتعكس اللوحة روح جازان الاستوائية وقصة أرضٍ تُثمر خيرًا وجمالًا."}}'::jsonb,4.4,29,'{"p-papaya","p-mango"}','{"everyday"}',11),
  ('p-gift-orchard','JAZ-GIFT-ORCH-250','orchard-box-250','gift_box','signature','The Orchard Box','علبة البستان','rose',null,'An assortment of milk-chocolate mini-tablets: cocoa butter, whole milk powder, cane sugar, cocoa mass, soya lecithin, natural vanilla, lavender, Damascena rose, Jazan jasmine, sun-dried papaya, Jazani mango.','تشكيلة ألواح صغيرة بالحليب: زبدة كاكاو، حليب كامل الدسم مجفف، سكر قصب، كتلة كاكاو، ليسيثين الصويا، فانيليا طبيعية، خزامى، ورد دمشقي، فُل جازان، ببايا مجففة بالشمس، مانجو جيزاني.','Ten 25 g mini-tablets from the milk side of the library — Signature Milk, Lavender, Damascena Rose and Jazan Jasmine twice over, then Sun Papaya and Jazani Mango to close. The orchard, boxed.','عشرة ألواح صغيرة زنة ٢٥ غرامًا من الجانب الحليبي في المكتبة — الحليب التوقيعية والخزامى والورد الدمشقي وفُل جازان، مرّتين لكلٍّ منها، ثم الببايا الشمسية والمانجو الجيزاني. البستان في علبة.','[{"en":"Milk","ar":"حليب"},{"en":"Soya","ar":"صويا"},{"en":"May contain nuts","ar":"قد يحتوي على مكسرات"}]'::jsonb,'{bestseller}',null,4.9,64,'{"p-gift-mountain","p-gift-library"}','{"gifting","eid","wedding"}',12),
  ('p-gift-mountain','JAZ-GIFT-MTN-250','mountain-box-250','gift_box','signature','The Mountain Box','علبة الجبل','coffee',null,'An assortment of dark-chocolate mini-tablets: cocoa mass, cane sugar, cocoa butter, soya lecithin, Khawlani coffee, milk powder, Red Sea salt, chili, sun-dried banana.','تشكيلة ألواح صغيرة داكنة: كتلة كاكاو، سكر قصب، زبدة كاكاو، ليسيثين الصويا، بن خولاني، حليب مجفف، ملح البحر الأحمر، فلفل، موز مجفف بالشمس.','Ten 25 g mini-tablets from the dark side — Single-Origin Dark 72%, Dark 60%, Khawlani Coffee and Sea Salt twice over, then Chili and Banana. The mountain and the salt flats, boxed.','عشرة ألواح صغيرة زنة ٢٥ غرامًا من الجانب الداكن — الداكنة ٧٢٪ والداكنة ٦٠٪ والبن الخولاني والداكنة بملح البحر، مرّتين لكلٍّ منها، ثم الفلفل الحار والموز. الجبل والملّاحات في علبة.','[{"en":"Milk","ar":"حليب"},{"en":"Soya","ar":"صويا"},{"en":"May contain nuts","ar":"قد يحتوي على مكسرات"}]'::jsonb,'{new}',null,4.8,37,'{"p-gift-orchard","p-gift-library"}','{"gifting","everyday"}',13),
